"""Route natural-language questions to verified RetailIQ AI reports."""

import re

import pandas as pd

from retailiq.assistant.analytics import (
    compare_stores,
    rank_sales,
)
from retailiq.assistant.context import (
    retrieve_evidence as retrieve_existing_evidence,
)
from retailiq.assistant.planner import (
    has_unsupported_scope,
    is_candidate_question,
    plan_question,
    requested_count,
)

# Reports generated by the earlier project phases.
from retailiq.config import ROOT

STORE_SOURCE = "business_analytics/02_store_performance.csv"
DEPARTMENT_SOURCE = "business_analytics/03_department_performance.csv"

STORE_REPORT = ROOT / "reports" / STORE_SOURCE
DEPARTMENT_REPORT = ROOT / "reports" / DEPARTMENT_SOURCE


# Verified sizes of the real aggregated reports.
MAX_STORES = 45
MAX_DEPARTMENTS = 81

NUMBER_WORDS = {
    "one": 1,
    "two": 2,
    "three": 3,
    "four": 4,
    "five": 5,
    "six": 6,
    "seven": 7,
    "eight": 8,
    "nine": 9,
    "ten": 10,
}

COUNT = (
    r"(?P<count>\d{1,3}|one|two|three|four|five|"
    r"six|seven|eight|nine|ten)"
)

ENTITY = r"(?P<entity>stores?|departments?|depts?)"

PREFIX = (
    r"(?:(?:which (?:are|were) the|"
    r"what (?:are|were) the|"
    r"show(?: me)?(?: the)?|"
    r"list(?: me)?(?: the)?)\s+)?"
)


# Several natural-language ranking patterns share one calculation.
RANK_PATTERNS = [
    re.compile(
        rf"{PREFIX}"
        rf"(?P<direction>top|bottom|highest|lowest)\s+"
        rf"{COUNT}\s+{ENTITY}"
        rf"(?:\s+(?:by|in terms of)\s+(?:total\s+)?sales)?",
        re.IGNORECASE,
    ),
    re.compile(
        rf"(?:which|what)\s+{COUNT}\s+{ENTITY}\s+"
        rf"(?:had|have|generated|recorded|made)\s+"
        rf"(?:the\s+)?"
        rf"(?P<direction>highest|lowest|most|least)\s+"
        rf"(?:total\s+)?sales",
        re.IGNORECASE,
    ),
    re.compile(
        rf"(?:list|show)(?:\s+me)?(?:\s+the)?\s+"
        rf"{COUNT}\s+"
        rf"(?P<direction>highest|lowest|best|worst)"
        rf"[-\s]selling\s+{ENTITY}",
        re.IGNORECASE,
    ),
]


# Each comparison pattern must explicitly contain two store IDs.
COMPARE_PATTERNS = [
    re.compile(
        r"compare\s+store\s+(\d{1,4})\s+"
        r"(?:and|with|vs|versus|to)\s+"
        r"store\s+(\d{1,4})"
        r"(?:\s+(?:by|on)\s+(?:total\s+)?sales)?",
        re.IGNORECASE,
    ),
    re.compile(
        r"compare\s+(?:the\s+)?(?:total\s+)?sales\s+"
        r"(?:of\s+|between\s+)?"
        r"store\s+(\d{1,4})\s+"
        r"(?:and|with|vs|versus|to)\s+"
        r"store\s+(\d{1,4})",
        re.IGNORECASE,
    ),
    re.compile(
        r"how\s+much\s+(?:more|less)\s+did\s+"
        r"store\s+(\d{1,4})\s+"
        r"(?:sell|generate|earn)\s+than\s+"
        r"store\s+(\d{1,4})",
        re.IGNORECASE,
    ),
    re.compile(
        r"(?:what is|what's)\s+the\s+"
        r"(?:(?:total\s+)?sales\s+)?difference\s+between\s+"
        r"store\s+(\d{1,4})\s+and\s+"
        r"store\s+(\d{1,4})",
        re.IGNORECASE,
    ),
    re.compile(
        r"how\s+do\s+store\s+(\d{1,4})\s+and\s+"
        r"store\s+(\d{1,4})\s+compare"
        r"(?:\s+(?:in|on|by)\s+(?:total\s+)?sales)?",
        re.IGNORECASE,
    ),
]


def normalize_question(question):
    """Standardize whitespace and common trailing punctuation."""

    normalized = re.sub(
        r"\s+",
        " ",
        question.strip().lower(),
    )

    normalized = normalized.rstrip("?.! ").strip()

    if normalized.startswith("please "):
        normalized = normalized[len("please ") :]

    return normalized


def parse_count(value):
    """Convert a written count into an integer."""

    if value in NUMBER_WORDS:
        return NUMBER_WORDS[value]

    return int(value)


def parse_custom_question(question):
    """Recognize known wording without calling Gemini."""

    text = normalize_question(question)

    for pattern in COMPARE_PATTERNS:
        match = pattern.fullmatch(text)

        if match:
            return {
                "operation": "compare_stores",
                "first_store": int(match.group(1)),
                "second_store": int(match.group(2)),
            }

    for pattern in RANK_PATTERNS:
        match = pattern.fullmatch(text)

        if not match:
            continue

        groups = match.groupdict()

        direction = groups["direction"].lower()
        count = parse_count(groups["count"].lower())
        entity = groups["entity"].lower()

        highest = direction in {
            "top",
            "highest",
            "most",
            "best",
        }

        operation = "rank_stores" if entity.startswith("store") else "rank_departments"

        return {
            "operation": operation,
            "count": count,
            "highest": highest,
        }

    return None


def is_sales_custom_request(question):
    """Identify ranking or comparison requests about retail entities."""

    text = question.lower()

    entity = re.search(
        r"\b(?:stores?|departments?|depts?)\b",
        text,
    )

    intent = re.search(
        r"\b(?:top|bottom|highest|lowest|best|worst|"
        r"most|least|rank|ranking|compare|comparison|"
        r"difference|gap|more|less|performing)\b",
        text,
    )

    return bool(entity and intent)


def is_explicit_custom_request(question):
    """Distinguish custom analytics from existing general questions."""

    text = question.lower()

    explicit = re.search(
        r"\b(?:rank|ranking|compare|comparison|"
        r"difference|gap|top|bottom)\b",
        text,
    )

    written_ranking = re.search(
        r"\b(?:best|worst|highest|lowest)"
        r"[-\s]+(?:selling|performing)\s+"
        r"(?:stores?|departments?|depts?)\b",
        text,
    )

    return bool(explicit or written_ranking or requested_count(question) is not None)


def unsupported(message):
    """Return a clear unsupported result without invented data."""

    return {
        "supported": False,
        "message": message,
        "evidence": [],
    }


def load_report(path):
    """Read an existing CSV report without modifying it."""

    if not path.is_file():
        raise FileNotFoundError("Required project report was not found.")

    return pd.read_csv(path)


def store_ranking(count, highest):
    """Calculate a sales ranking using the verified store report."""

    if not 1 <= count <= MAX_STORES:
        raise ValueError("Store ranking size must be between 1 and 45.")

    data = load_report(STORE_REPORT)

    ranked = rank_sales(
        data,
        id_column="Store",
        sales_column="Total_Sales",
        count=count,
        highest=highest,
    )

    records = []

    for index, row in ranked.iterrows():
        records.append(
            {
                "Rank": index + 1,
                "Store": int(row["Store"]),
                "Total_Sales": round(
                    float(row["Total_Sales"]),
                    2,
                ),
            }
        )

    direction = "highest" if highest else "lowest"

    return {
        "supported": True,
        "topic": "custom_store_ranking",
        "message": "",
        "evidence": [
            {
                "source": STORE_SOURCE,
                "description": (
                    f"The {count} stores with the {direction} "
                    "historical total sales, ranked from the "
                    "saved store performance report."
                ),
                "records": records,
            }
        ],
    }


def department_ranking(count, highest):
    """Calculate rankings for up to 81 departments."""

    if not 1 <= count <= MAX_DEPARTMENTS:
        raise ValueError("Department ranking size must be between 1 and 81.")

    data = load_report(DEPARTMENT_REPORT)

    ranked = rank_sales(
        data,
        id_column="Dept",
        sales_column="Total_Sales",
        count=count,
        highest=highest,
    )

    records = []

    for index, row in ranked.iterrows():
        records.append(
            {
                "Rank": index + 1,
                "Dept": int(row["Dept"]),
                "Total_Sales": round(
                    float(row["Total_Sales"]),
                    2,
                ),
            }
        )

    direction = "highest" if highest else "lowest"

    return {
        "supported": True,
        "topic": "custom_department_ranking",
        "message": "",
        "evidence": [
            {
                "source": DEPARTMENT_SOURCE,
                "description": (
                    f"The {count} departments with the {direction} "
                    "historical total sales, ranked from the "
                    "saved department performance report."
                ),
                "records": records,
            }
        ],
    }


def store_comparison(first_store, second_store):
    """Calculate a comparison using real store sales totals."""

    data = load_report(STORE_REPORT)

    result = compare_stores(
        data,
        first_store=first_store,
        second_store=second_store,
        id_column="Store",
        sales_column="Total_Sales",
    )

    difference = round(
        abs(result["difference"]),
        2,
    )

    higher_store = result["higher_sales_store"]

    records = [
        {
            "Store": result["first_store"],
            "Total_Sales": round(
                result["first_sales"],
                2,
            ),
            "Absolute_Sales_Difference": difference,
            "Higher_Sales_Store": higher_store,
        },
        {
            "Store": result["second_store"],
            "Total_Sales": round(
                result["second_sales"],
                2,
            ),
            "Absolute_Sales_Difference": difference,
            "Higher_Sales_Store": higher_store,
        },
    ]

    return {
        "supported": True,
        "topic": "custom_store_comparison",
        "message": "",
        "evidence": [
            {
                "source": STORE_SOURCE,
                "description": (
                    f"Historical total sales comparison between "
                    f"Store {result['first_store']} and "
                    f"Store {result['second_store']}. "
                    "The sales difference was calculated in Python."
                ),
                "records": records,
            }
        ],
    }


def retrieve_evidence(question):
    """Use approved custom calculations or the existing engine."""

    # Check unsupported filters BEFORE running a calculation.
    # A request for 2025 must not become an all-time sales result.
    if is_sales_custom_request(question) and has_unsupported_scope(question):
        return unsupported(
            "This question requires a time period or metric "
            "not available in the aggregated sales reports. "
            "Try asking about historical total sales instead."
        )

    # Common supported patterns do not need Gemini.
    request = parse_custom_question(question)

    if request is None:
        # New wording may require Gemini to select an operation.
        if is_sales_custom_request(question) and is_explicit_custom_request(question):
            if not is_candidate_question(question):
                return unsupported("This custom sales question cannot be safely interpreted.")

            request = plan_question(question)

            if request is None:
                return unsupported(
                    "I couldn't safely interpret this sales "
                    "question. Try specifying a ranking or "
                    "two store IDs."
                )

        else:
            # Keep all existing forecasting, anomaly, SHAP
            # and ordinary business questions unchanged.
            return retrieve_existing_evidence(question)

    try:
        operation = request["operation"]

        if operation == "compare_stores":
            return store_comparison(
                request["first_store"],
                request["second_store"],
            )

        if operation == "rank_stores":
            return store_ranking(
                request["count"],
                request["highest"],
            )

        if operation == "rank_departments":
            return department_ranking(
                request["count"],
                request["highest"],
            )

        return unsupported("This analytics operation is not supported.")

    except (
        FileNotFoundError,
        ValueError,
        KeyError,
        pd.errors.ParserError,
        pd.errors.EmptyDataError,
    ):
        return unsupported(
            "The requested analysis couldn't be calculated "
            "from the saved project reports. Check the "
            "requested IDs, ranking size and available data."
        )
